module subset_sum_mask (\n    input clk, rst_n,\n    input start,\n    input [3:0] n,\n    input [4:0] k,\n    input [7:0] coin_in,\n    output reg done,\n    output reg [16:0] result_mask\n);\n\nparameter MAX_N = 8;\nparameter MAX_K = 16;\n\nlocalparam [1:0] IDLE  = 2'd0;\nlocalparam [1:0] PROCESS = 2'd1;\nlocalparam [1:0] DONE_STATE = 2'd2;\n\nreg [1:0] state, next_state;\nreg [3:0] counter, next_counter;\nreg [16:0] dp [0:16];  // dp[s] for s=0 to 16\nreg [4:0] k_reg;\nreg [3:0] n_reg;\ninteger s;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        counter <= 4'd0;\n        k_reg <= 5'd0;\n        n_reg <= 4'd0;\n        for (s = 0; s <= MAX_K; s = s + 1) begin\n            dp[s] <= 17'd0;\n        end\n        dp[0] <= 17'd1;  // Sum 0 is possible\n        done <= 1'b0;\n        result_mask <= 17'd0;\n    end else begin\n        state <= next_state;\n        counter <= next_counter;\n        if (state == IDLE && start) begin\n            k_reg <= k;\n            n_reg <= n;\n        end\n        \n        if (state == PROCESS) begin\n            for (s = 0; s <= MAX_K; s = s + 1) begin\n                if (s < coin_in) begin\n                    dp[s] <= dp[s];\n                end else begin\n                    dp[s] <= dp[s] | dp[s - coin_in] | (dp[s - coin_in] << coin_in);\n                end\n            end\n        end\n        \n        done <= (next_state == DONE_STATE);\n        if (state == DONE_STATE) begin\n            result_mask <= dp[k_reg];\n        end\n    end\nend\n\nalways @(*) begin\n    next_state = state;\n    next_counter = counter;\n    case (state)\n        IDLE: begin\n            if (start) begin\n                next_state = PROCESS;\n                next_counter = 4'd0;\n            end\n        end\n        PROCESS: begin\n            if (counter < n_reg - 4'd1) begin\n                next_counter = counter + 4'd1;\n            end else begin\n                next_state = DONE_STATE;\n            end\n        end\n        DONE_STATE: next_state = IDLE;\n        default: next_state = IDLE;\n    endcase\nend\n\nendmodule